    const { discount, minOrder, maxDiscount, singleUse } = this.coupons[code];
    const usedSet = this.used[code];
    if (singleUse && usedSet.has(userId)) {
        this._logAudit('ALREADY_USED', code, userId, orderTotal, 0, ts);
        return { success: false, reason: 'already_used' };
    }
    if (orderTotal < minOrder) {
        this._logAudit('BELOW_MINIMUM', code, userId, orderTotal, 0, ts);
        return { success: false, reason: 'below_minimum' };
    }
    let discountApplied = orderTotal * discount;
    if (discountApplied > maxDiscount) {
        discountApplied = maxDiscount;
    }
    usedSet.add(userId);
    this._logAudit('REDEEMED', code, userId, orderTotal, discountApplied, ts);
    return { success: true, discount: discountApplied };
}

