class CreditScorer {
    // Tiers: 'poor' (0-399), 'fair' (400-599), 'good' (600-749), 'excellent' (750-850)
    static TIERS = [
        { name: 'poor', min: 0, max: 399 },
        { name: 'fair', min: 400, max: 599 },
        { name: 'good', min: 600, max: 749 },
        { name: 'excellent', min: 750, max: 850 },
    ];

    constructor(initialScore, cooldownPeriod = 0) {
        this.score = Math.max(0, Math.min(850, initialScore));
        this.cooldownPeriod = cooldownPeriod;
        this.lastTransitionTs = -Infinity;
        this.tier = this._getTier(this.score);
        this.audit = [];
    }

    _getTier(score) {
        for (const t of CreditScorer.TIERS) {
            if (score >= t.min && score <= t.max) return t.name;
        }
        return score > 850 ? 'excellent' : 'poor';
    }

    _clamp(score) {
        return Math.max(0, Math.min(850, score));
