const assert = require('assert');

class ExpenseReport {
    constructor(employeeId, categoryLimits) {
        this.employeeId = employeeId;
        this.categoryLimits = categoryLimits; // e.g. { travel: 500, meals: 200 }
        this.items = [];
        this.audit = [];
        this.categoryTotals = {};
        this.status = 'draft';
        this.reimbursement = 0;
    }

golden_completion:
addExpense(category, amount, receiptId) {
    if (this.status !== 'draft')
        return (this.audit.push({ action: 'reject_add', reason: 'not_draft', receiptId }), false);
    if (!receiptId || amount <= 0)
        return (this.audit.push({ action: 'reject_add', reason: 'invalid_input', receiptId }), false);
    const limit = this.categoryLimits[category];
    const cur = this.categoryTotals[category] || 0;
    const capped = limit !== undefined ? Math.min(amount, limit - cur) : amount;
    if (capped <= 0)
        return (this.audit.push({ action: 'reject_add', reason: 'over_limit', category, amount }), false);
    this.categoryTotals[category] = cur + capped;
    this.items.push({ category, amount: capped, receiptId, originalAmount: amount });
    this.reimbursement += capped;
    this.audit.push({ action: 'add', category, capped, originalAmount: amount, receiptId });
    return true;
}

suffix:
    submit() {
        if (this.status !== 'draft' || this.items.length === 0) return false;
        this.status = 'submitted';
        this.audit.push({ action: 'submit', itemCount: this.items.length });
        return true;
    }
}

