const assert = require('assert');

class SubscriptionManager {
    constructor(plans) {
        this.plans = plans; // { planName: { price: N, features: [...] } }
        this.currentPlan = null;
        this.billingStart = 0;
        this.cycleLength = 30; // days
        this.balance = 0; // credit/debit carried forward
        this.changes = [];
    }

    subscribe(planName, day) {
        if (this.currentPlan) return false;
        this.currentPlan = planName;
        this.billingStart = day;
        this.balance = 0;
        this.changes.push({ action: 'subscribe', plan: planName, day });
        return true;
    }

golden_completion:
changePlan(newPlan, day) {
    if (!this.currentPlan || newPlan === this.currentPlan || !this.plans[newPlan]) return false;
    const daysUsed = day - this.billingStart;
    if (daysUsed < 0 || daysUsed > this.cycleLength) return false;
    const oldPlan = this.currentPlan;
    const remaining = (this.cycleLength - daysUsed) / this.cycleLength;
    const credit = this.plans[oldPlan].price * remaining;
    const charge = this.plans[newPlan].price * remaining;
    this.balance += credit - charge;
    this.currentPlan = newPlan;
    this.billingStart = day;
    this.changes.push({ action: 'change', from: oldPlan, to: newPlan, day,
        credit: parseFloat(credit.toFixed(2)), charge: parseFloat(charge.toFixed(2)) });
    return true;
}

