const assert = require('assert');

class Warehouse {
    constructor(bins) {
        // bins: { binId: { zone: string, capacity: number } }
        this.bins = {};
        for (const [id, cfg] of Object.entries(bins)) {
            this.bins[id] = { ...cfg, items: [], currentLoad: 0 };
        }
        this.zoneRules = { cold: ['cold'], dry: ['dry', 'ambient'], hazmat: ['hazmat'] };
        this.log = [];
    }

golden_completion:
assignItem(itemId, itemZone, itemSize, preferredBin) {
    const compat = this.zoneRules[itemZone];
    if (!compat) return (this.log.push({ action: 'reject', itemId, reason: 'unknown_zone' }), null);
    const tryBin = (binId) => {
        const bin = this.bins[binId];
        if (!bin || !compat.includes(bin.zone) || bin.currentLoad + itemSize > bin.capacity) return false;
        bin.items.push({ itemId, size: itemSize, ts: Date.now() });
        bin.currentLoad += itemSize;
        this.log.push({ action: 'assign', itemId, binId, size: itemSize });
        return true;
    };
    if (preferredBin && tryBin(preferredBin)) return preferredBin;
    for (const binId of Object.keys(this.bins)) if (tryBin(binId)) return binId;
    return (this.log.push({ action: 'reject', itemId, reason: 'no_space' }), null);
}

suffix:
    evictOldest(binId) {
        const bin = this.bins[binId];
        if (!bin || bin.items.length === 0) return null;
        const item = bin.items.shift(); // FIFO
        bin.currentLoad -= item.size;
        this.log.push({ action: 'evict', itemId: item.itemId, binId });
        return item.itemId;
    }
}

