    }
    const allowedZones = this.zoneRules[zone];
    // try preferred bin first
    if (preferredBinId && this.bins[preferredBinId]) {
        const bin = this.bins[preferredBinId];
        if (allowedZones.includes(bin.zone) && (bin.capacity - bin.currentLoad) >= size) {
            bin.items.push({ itemId, size });
            bin.currentLoad += size;
            this.log.push({ action: 'assign', itemId, binId: preferredBinId, zone });
            return preferredBinId;
        }
    }
    // try any compatible bin
    for (const [binId, bin] of Object.entries(this.bins)) {
        if (allowedZones.includes(bin.zone) && (bin.capacity - bin.currentLoad) >= size) {
            bin.items.push({ itemId, size });
            bin.currentLoad += size;
            this.log.push({ action: 'assign', itemId, binId, zone });
            return binId;
        }
    }
    // no suitable bin
    this.log.push({ action: 'fail', itemId, zone, reason: 'no_space' });
    return null;
}

