const assert = require('assert');

class ComplianceChecker {
    constructor(rules, exceptions) {
        // rules: [{ id, check: fn, severity: 'error'|'warning' }] — evaluated in order, first error stops
        // exceptions: { ruleId: { grantedTo: [...], expiresAt: number } }
        this.rules = rules;
        this.exceptions = exceptions;
        this.auditLog = [];
    }

golden_completion:
evaluate(entityId, entity, currentDay) {
    const results = [];
    let blocked = false;
    for (const rule of this.rules) {
        const exc = this.exceptions[rule.id];
        if (exc && exc.grantedTo.includes(entityId) && exc.expiresAt > currentDay) {
            results.push({ ruleId: rule.id, status: 'exempted' });
            this.auditLog.push({ entityId, ruleId: rule.id, status: 'exempted', day: currentDay });
            continue;
        }
        const passed = rule.check(entity);
        if (!passed && rule.severity === 'error') {
            results.push({ ruleId: rule.id, status: 'fail', severity: 'error' });
            this.auditLog.push({ entityId, ruleId: rule.id, status: 'fail', day: currentDay });
            blocked = true; break;
        }
        const st = passed ? 'pass' : 'warn';
        results.push({ ruleId: rule.id, status: st, severity: passed ? null : 'warning' });
        this.auditLog.push({ entityId, ruleId: rule.id, status: st, day: currentDay });
    }
    return { entityId, compliant: !blocked, results };
}

