processReturn(orderId, items, discount, daysSincePurchase) {
    const subtotal = items.reduce((acc, item) => acc + item.price * item.qty, 0);
    let status, method, restocking, refund, credit;
    if (daysSincePurchase <= this.fullRefundDays) {
        status = 'approved';
        method = 'refund';
        restocking = 0;
        refund = subtotal;
        credit = 0;
    } else if (daysSincePurchase <= this.creditOnlyDays) {
        status = 'approved';
        method = 'credit';
        restocking = subtotal * this.restockingPct;
        refund = 0;
        credit = subtotal - restocking;
    } else {
        status = 'rejected';
        method = null;
        restocking = 0;
        refund = 0;
        credit = 0;
    }
    const record = {
        orderId,
        subtotal,
        status,
        method,
        restocking,
        refund,
        credit,
        items,
        daysSincePurchase,
        discount
    };
    if (status === 'rejected') record.reason = 'past_return_window';
    this.returns.push(record);
    return record;
}

