const esc = new EscrowAccount(10000, 0.10);
esc.addMilestone('design', true);
esc.addMilestone('build', true);
esc.addMilestone('test', false);

// Can't release with incomplete required milestones
let r1 = esc.release('r1', 1000);
console.assert(r1.status === 'milestones-pending', 'Should block on milestones');

esc.completeMilestone('design');
esc.completeMilestone('build');

// Defect blocks release
esc.reportDefect('cracked foundation');
let r2 = esc.release('r2', 2000);
console.assert(r2.status === 'blocked-defects', 'Should block on defects');

// Resolve defect, now release works
esc.resolveDefect('cracked foundation');
let r3 = esc.release('r3', 3000);
console.assert(r3.status === 'released', 'Should release');
// holdback = 10% of 10000 = 1000, so available = 10000 - 1000 - 0 = 9000
console.assert(r3.amount === 9000, 'Should release 9000');
console.assert(esc.released === 9000, 'Total released should be 9000');

// Idempotent: same releaseId returns duplicate
let r4 = esc.release('r3', 4000);
console.assert(r4.status === 'duplicate', 'Duplicate release');
console.assert(r4.amount === 0, 'Duplicate amount 0');
console.assert(esc.released === 9000, 'Released unchanged after dup');

// Audit log
console.assert(esc.releaseLog.length === 1, 'One release logged');
console.assert(esc.releaseLog[0].amount === 9000, 'Log amount');
console.assert(esc.releaseLog[0].timestamp === 3000, 'Log timestamp');

