    }

    // Inventory check
    if (!this.inventory[drug] || this.inventory[drug] < qty) {
        return { status: 'out-of-stock', copay: 0 };
    }

    // Extract date (YYYY-MM-DD) for daily limit tracking
    const date = new Date(timestamp);
    const dateStr = date.toISOString().split('T')[0];

    if (drugInfo.controlled) {
        // Daily controlled limit
        const currentDaily = this.dailyControlled[dateStr] || 0;
        if (currentDaily + qty > drugInfo.maxDaily) {
            return { status: 'daily-limit-exceeded' };
        }

