                if (timeDiff < drugInfo.minRefillMs) {
                    return { status: 'refill-too-soon' };
                }
            }
        }
    }

    // Dispense: update inventory
    this.inventory[drug] -= qty;

    // Update daily controlled total
    if (drugInfo.controlled) {
        this.dailyControlled[dateStr] = (this.dailyControlled[dateStr] || 0) + qty;
    }

    // Calculate copay based on tier
    const copay = drugInfo.copay[tier] || 0;

    // Record dispensed log
    const logEntry = { rxId, drug, qty, copay, timestamp };
    this.dispensedLog.push(logEntry);

    // Mark rxId as processed
    this._dispensedRxIds.add(rxId);

    return {
        status: 'dispensed',
        copay,
        rxId,
        drug,
        qty,
        tier,
        timestamp
    };
}

