class MenuPricing {
    constructor() {
        this.items = {};            // name -> { basePrice, happyHourPrice, ingredients: [...] }
        this.combos = {};           // comboName -> { items: [name,...], discount: 0.0-1.0 }
        this.orders = [];           // { items: [...], total, ingredientCost, timestamp }
        this.ingredientCosts = {};  // ingredient -> cost per unit
    }

    addItem(name, basePrice, happyHourPrice, ingredients = []) {
        this.items[name] = { basePrice, happyHourPrice, ingredients };
    }

    addCombo(comboName, itemNames, discount) {
        this.combos[comboName] = { items: itemNames, discount };
    }

    setIngredientCost(ingredient, cost) {
        this.ingredientCosts[ingredient] = cost;
    }

    // Happy hour is between 16:00 and 18:00 (hour 16 and 17)
    _isHappyHour(hour) { return hour >= 16 && hour < 18; }

