order(itemNames, hour, timestamp) {
    const isHH = this._isHappyHour(hour);
    let prices = itemNames.map(n => {
        const item = this.items[n]; if (!item) throw new Error(`Unknown item: ${n}`);
        return isHH ? item.happyHourPrice : item.basePrice;
    });
    for (const [, combo] of Object.entries(this.combos)) {
        const ci = [...combo.items].sort(), oi = [...itemNames].sort();
        if (ci.length === oi.length && ci.every((v, i) => v === oi[i])) {
            prices = [prices.reduce((a, b) => a + b, 0) * (1 - combo.discount)]; break;
        }
    }
    const total = Math.round(prices.reduce((a, b) => a + b, 0) * 100) / 100;
    let ingredientCost = 0;
    for (const n of itemNames) for (const ing of this.items[n].ingredients) ingredientCost += this.ingredientCosts[ing] || 0;
    this.orders.push({ items: itemNames, total, ingredientCost, timestamp });
    return { total, ingredientCost, margin: Math.round((total - ingredientCost) * 100) / 100 };
}

